#include <omp.h>
#include <array>
#include <cstddef>
#include <vector>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 256>> local_hists(
        static_cast<std::size_t>(max_threads),
        std::array<size_t, 256>{}
    );

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(image.size());

    #pragma omp parallel default(none) shared(image, local_hists, n)
    {
        const int tid = omp_get_thread_num();
        std::array<size_t, 256> &local = local_hists[static_cast<std::size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const int value = image[static_cast<std::size_t>(i)];
            if (static_cast<unsigned int>(value) < 256u) {
                ++local[static_cast<std::size_t>(value)];
            }
        }
    }

    for (const auto &hist : local_hists) {
        for (std::size_t b = 0; b < 256; ++b) {
            bins[b] += hist[b];
        }
    }
}
